const materials={ground:mat(0x55574b),road:mat(0x343936),concrete:mat(0x726f61),dark:mat(0x222b29),rust:mat(0x784c38),green:mat(0x475447),wood:mat(0x655542),yellow:mat(0xb68b49),skin:mat(0x9a7962),cloth:mat(0x44483e),enemy:mat(0x675c49),red:mat(0x7f382f),blue:mat(0x485c5d)};
