let state='title',chapter=0,weapon=0,health=100,ammo=[6,30],reserve=[36,150],enemies=[],props=[],objectiveObject=null,truck=null,inTruck=false,truckProgress=0,killCount=0,requiredKills=0,interacted=false,locked=false,shootCooldown=0,reloadTimer=0,damageTimer=0,radioTimer=0,chapterTime=0,shake=0;
const names=['A ESTRADA VAZIA','O POSTO DE CONTROLE','A FLORESTA DE ANTENAS','A CIDADE SUBMERSA','O ÚLTIMO INVERNO'];
