let audioCtx=null,master=null,musicNodes=[];
function startAudio(){if(audioCtx)return;audioCtx=new (window.AudioContext||window.webkitAudioContext)();master=audioCtx.createGain();master.gain.value=.18;master.connect(audioCtx.destination);const notes=[55,82.4,110,164.8];notes.forEach((f,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain(),lp=audioCtx.createBiquadFilter();o.type=i===1?'triangle':'sine';o.frequency.value=f;g.gain.value=i===0?.12:.035;lp.type='lowpass';lp.frequency.value=400;o.connect(lp);lp.connect(g);g.connect(master);o.start();musicNodes.push({o,g});});const lfo=audioCtx.createOscillator(),lg=audioCtx.createGain();lfo.frequency.value=.11;lg.gain.value=8;lfo.connect(lg);lg.connect(musicNodes[0].o.frequency);lfo.start();musicNodes.push({o:lfo,g:lg});}
function tone(freq,dur,type='sine',vol=.15){if(!audioCtx)return;const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.setValueAtTime(freq,audioCtx.currentTime);g.gain.setValueAtTime(vol,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+dur);o.connect(g);g.connect(master);o.start();o.stop(audioCtx.currentTime+dur)}
function noise(dur=.15,vol=.16){if(!audioCtx)return;const buffer=audioCtx.createBuffer(1,audioCtx.sampleRate*dur,audioCtx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*(1-i/data.length);const s=audioCtx.createBufferSource(),g=audioCtx.createGain();s.buffer=buffer;g.gain.value=vol;s.connect(g);g.connect(master);s.start()}
function box(parent,x,y,z,sx,sy,sz,material,cast=true){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.position.set(x,y,z);m.castShadow=cast;m.receiveShadow=true;parent.add(m);return m}
function cylinder(parent,x,y,z,r1,r2,h,material,segments=8){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material);m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m}
function clear(group){while(group.children.length){const o=group.children.pop();if(o.geometry)o.geometry.dispose();}}
function makeGround(){box(world,0,-.16,-28,100,.3,110,materials.ground,false);box(world,0,.005,-28,7,.08,110,materials.road,false);for(let z=18;z>-78;z-=13){box(world,0,.06,z, .12,.025,4,mat(0x9b8c65),false)}
 // edges, landscape ridges, rubble and landmark buildings
 for(let side of [-1,1]){for(let i=0;i<15;i++){let z=14-i*6.3,x=side*(8+Math.random()*13),h=1+Math.random()*3;const b=box(world,x,h/2-.05,z,2+Math.random()*3,h,2+Math.random()*4,[materials.concrete,materials.rust,materials.wood][Math.floor(Math.random()*3)]);if(Math.random()<.7)box(world,x+(Math.random()-.5)*2,h+.25,z,.2,.4,.2,materials.dark);props.push({x,z,r:1.8})}}
 // telephone poles and wires
 for(let z=15;z>-75;z-=14){for(const x of [-7,7]){cylinder(world,x,3,z,.12,.17,6,materials.wood);box(world,x,5.9,z,.8,.12,.12,materials.wood);}}
 for(let z=14;z>-67;z-=14){const curve=new THREE.QuadraticBezierCurve3(new THREE.Vector3(-7,6,z),new THREE.Vector3(0,4.7,z-7),new THREE.Vector3(7,6,z-14));const wire=new THREE.Mesh(new THREE.TubeGeometry(curve,24,.025,4,false),mat(0x252928));world.add(wire)}
 // distant dark ridge silhouettes
 for(let i=0;i<18;i++){const m=new THREE.Mesh(new THREE.ConeGeometry(9+Math.random()*9,5+Math.random()*8,5),mat(i%2?0x49534c:0x555b51));m.position.set(-65+i*8,1,-75-Math.random()*12);world.add(m)}
}
function makeTree(x,z,dead=false){const g=new THREE.Group();g.position.set(x,0,z);cylinder(g,0,1.2,0,.16,.28,2.4,mat(0x39362f));for(let i=0;i<4;i++){const branch=cylinder(g,0,2+i*.45,0,.04,.14,1.2,mat(0x39362f));branch.rotation.z=(i%2?1:-1)*.55;if(!dead){const leaf=new THREE.Mesh(new THREE.ConeGeometry(1.05,2.3,6),mat(i%2?0x39463d:0x465141));leaf.position.y=2.5+i*.35;g.add(leaf)}}world.add(g)}
function addBuilding(x,z,w,h,d,kind=0){const color=[0x69695d,0x575a52,0x786a59,0x4c5550][kind%4],wall=mat(color),g=new THREE.Group();g.position.set(x,0,z);box(g,0,h/2,0,w,h,d,wall);box(g,0,h+.08,0,w+.3,.2,d+.3,mat(0x363b37));for(let y=1.4;y<h-1;y+=2.2)for(let wx=-w/2+1;wx<w/2-.5;wx+=2.4){box(g,wx,y,-d/2-.015,.85,1.1,.04,mat(Math.random()<.3?0x96917c:0x252f30));box(g,wx,y,.0,.08,1.12,.08,mat(0x363b37))}if(kind===2){box(g,-w*.22,h+.45,0,.4,.7,.4,materials.rust);box(g,w*.22,h+.45,0,.4,.7,.4,materials.rust)}world.add(g);props.push({x,z,r:Math.max(w,d)*.38});return g}
function createHuman(x,z,boss=false){const g=new THREE.Group();g.position.set(x,0,z);const clothes=mat(boss?0x393b36:0x4e5145),head=mat(0x8c715a),gear=mat(boss?0x333333:0x6a604d);const torso=box(g,0,1.05,0,boss?.75:.52,boss?1.05:.78,.32,clothes);box(g,0,boss?1.73:1.58,0,.32,.34,.32,head);box(g,0,boss?1.95:1.8,0,.38,.1,.38,gear);for(const s of [-1,1]){const arm=box(g,s*(boss?.52:.35),1.2,-.12,.18,.62,.2,clothes);arm.rotation.z=s*.13;const leg=box(g,s*.17,.42,0,.2,.72,.24,gear);leg.rotation.x=(Math.random()-.5)*.1}const gun=box(g,.2,1.03,-.43,.12,.12,.7,mat(0x252b29,.5,.5));g.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true}});actors.add(g);return {group:g,x,z,hp:boss?16:3,maxHp:boss?16:3,boss,attack:0,walk:Math.random()*5,speed:boss?1.0:.63+Math.random()*.25,alive:true,phase:0};}
function addTruck(x,z){const g=new THREE.Group();g.position.set(x,0,z);const body=box(g,0,.85,0,2.2,.65,3.8,mat(0x526653,.65));body.castShadow=true;box(g,0,1.5,-.35,1.9,.8,1.75,mat(0x526653,.5));box(g,0,1.5,-1.25,1.65,.53,.04,mat(0x263230,.4));box(g,0,1.12,1.05,1.7,.45,1.35,mat(0x405342));for(const xw of [-1,1])for(const zw of [-1.25,1.25]){const w=cylinder(g,xw,.45,zw,.43,.43,.25,mat(0x191b19),12);w.rotation.z=Math.PI/2;const hub=cylinder(g,xw*1.01,.45,zw,.19,.19,.27,mat(0x8e8063),8);hub.rotation.z=Math.PI/2}box(g,-.7,.97,-1.34,.3,.2,.05,mat(0xb9874a));box(g,.7,.97,-1.34,.3,.2,.05,mat(0xb9874a));g.traverse(o=>{if(o.isMesh)o.castShadow=true});world.add(g);truck=g;props.push({x,z,r:2.5});}
function makeObjective(x,z){if(objectiveObject){world.remove(objectiveObject);objectiveObject=null}const g=new THREE.Group();g.position.set(x,0,z);const beacon=new THREE.Mesh(new THREE.OctahedronGeometry(.32,0),new THREE.MeshBasicMaterial({color:0xe9a45b}));beacon.position.y=2.25;g.add(beacon);const ring=new THREE.Mesh(new THREE.TorusGeometry(.65,.035,6,24),new THREE.MeshBasicMaterial({color:0xe0a362,transparent:true,opacity:.8}));ring.rotation.x=Math.PI/2;ring.position.y=.12;g.add(ring);const stem=cylinder(g,0,1.1,0,.035,.035,2.1,new THREE.MeshBasicMaterial({color:0xdfa464,transparent:true,opacity:.45}));g.add(stem);world.add(g);objectiveObject=g;}
function buildChapter(n){clear(world);clear(actors);clear(effects);enemies=[];props=[];truck=null;inTruck=false;interacted=false;killCount=0;chapter=n;camera.position.set(0,1.68,7);camera.rotation.set(0,0,0);scene.fog.color.set(n===3?0x6d7773:n===4?0x69716c:0x788079);scene.background.copy(scene.fog.color);sun.intensity=n===4?1.05:2.1;fill.intensity=n>=3?38:24;makeGround();
 if(n===0){for(let i=0;i<7;i++){makeTree(-11-i%2*4,-4-i*8);makeTree(11+i%2*4,-2-i*8)}addBuilding(-13,-23,8,5,7,2);addBuilding(13,-43,7,7,8,0);for(let i=0;i<5;i++)box(world,(Math.random()-.5)*9,.3,-9-i*9,Math.random()*1+.7,.6,Math.random()*1+.7,materials.rust)}
 if(n===1){addBuilding(-12,-19,10,5,8,0);addBuilding(12,-36,10,6,8,1);box(world,0,1,-26,7,2,1,materials.rust);box(world,0,2.2,-26,.35,.3,1,materials.yellow);for(let x of [-7,7])box(world,x,1.1,-44,1,2.2,1,materials.dark);addTruck(0,-14);for(let i=0;i<7;i++)makeTree((i%2?1:-1)*(10+Math.random()*4),-i*8)}
 if(n===2){for(let i=0;i<22;i++)makeTree((Math.random()<.5?-1:1)*(8+Math.random()*17),5-Math.random()*78,true);addBuilding(-12,-34,11,5,10,1);addBuilding(11,-48,9,4,9,0);for(let i=0;i<3;i++){const mast=cylinder(world,(i-1)*5,7,-38,.11,.15,14,materials.dark);box(world,(i-1)*5,12,-38,.8,.14,.15,materials.rust);for(let y=4;y<12;y+=2)box(world,(i-1)*5,y,-38,.55,.09,.1,materials.dark)}box(world,0,.08,-46,3,.1,3,mat(0x333a36))}
 if(n===3){for(let i=0;i<7;i++){addBuilding(-11,-9-i*9,8,5+(i%3)*1.3,7,i%4);addBuilding(12,-14-i*9,8,6+(i%2)*2,8,(i+2)%4)}for(let i=0;i<7;i++)makeTree((i%2?1:-1)*(5+Math.random()*3),-8-i*8);box(world,0,.08,-22,5,.1,6,mat(0x56645e));for(let i=0;i<6;i++)box(world,(Math.random()-.5)*5,.25,-15-i*7,.5,.45,.6,materials.rust)}
 if(n===4){addBuilding(-12,-23,10,6,9,2);addBuilding(12,-32,10,7,9,0);addBuilding(0,-57,16,8,12,1);for(let i=0;i<11;i++)makeTree((i%2?1:-1)*(8+Math.random()*10),-i*6,true);box(world,0,.1,-57,5,.2,4,materials.dark);for(let x of [-2,2]){cylinder(world,x,5,-58,.13,.2,10,materials.rust);box(world,x,10,-58,.8,.12,.15,materials.yellow)}}
 requiredKills=n===0?3:n===1?4:n===2?5:n===3?6:1;
 const positions=n===0?[[-4,-13],[4,-23],[-3,-37],[5,-48]]:n===1?[[-4,-23],[5,-33],[-5,-40],[3,-49],[0,-58]]:n===2?[[-4,-18],[4,-26],[-3,-35],[5,-43],[-4,-53],[2,-63]]:n===3?[[-4,-17],[4,-25],[-3,-34],[4,-44],[-5,-54],[3,-63],[0,-70]]:[[4,-28],[-4,-40],[1,-51]];
 positions.forEach((p,i)=>{if(n===4&&i<2)enemies.push(createHuman(...p,false));else enemies.push(createHuman(...p,n===4&&i===2))});if(n===4){enemies.forEach(e=>{if(e.boss){e.hp=24;e.maxHp=24}})}
 const objZ=n===0?-59:n===1?-55:n===2?-71:n===3?-73:-61;makeObjective(n===0?0:n===1?0:n===2?0:0,objZ);chapterTime=0;updateChapterUI();$('objective').textContent=goals[n];$('location-name').textContent=locations[n];$('hud-chapter').textContent=roman[n];$('objective-count').textContent=`0 / ${requiredKills}`;showChapterCard();setTimeout(()=>radio(chapterRadio[n][0]),2400);
}
function showChapterCard(){const el=$('chapter-card');$('chapter-number').textContent=roman[chapter];$('chapter-title').textContent=names[chapter];$('chapter-subtitle').textContent=subtitles[chapter];el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3100)}
function updateChapterUI(){$('hud-chapter').textContent=roman[chapter];$('location-name').textContent=locations[chapter];$('objective').textContent=goals[chapter]}
function radio(text){const e=$('radio-caption');$('radio-text').textContent=text;e.classList.add('show');radioTimer=6;tone(380,.2,'sine',.04)}
function setHUD(on){$('hud').classList.toggle('hidden',!on);}
function startGame(){startAudio();$('title-screen').classList.remove('visible');$('pause-screen').classList.remove('visible');$('end-screen').classList.remove('visible');state='playing';health=100;ammo=[6,30];reserve=[36,150];weapon=0;buildChapter(0);setHUD(true);renderer.domElement.requestPointerLock?.();}
function setPaused(paused){if(paused){state='paused';$('pause-screen').classList.add('visible');$('pause-sector').textContent=String(chapter+1).padStart(2,'0');document.exitPointerLock?.()}else{state='playing';$('pause-screen').classList.remove('visible');renderer.domElement.requestPointerLock?.()}}
function endGame(won){state='ended';setHUD(false);document.exitPointerLock?.();$('ending-title').innerHTML=won?'AINDA<br><i>HÁ AMANHÃ.</i>':'A FITA<br><i>ACABOU.</i>';$('ending-copy').textContent=won?'A estrada continua. Mas, pela primeira vez, você não está sozinho.':'O silêncio voltou. A zona guardará o resto da história.';$('end-screen').classList.add('visible')}
$('start-button').onclick=startGame;$('resume-button').onclick=()=>setPaused(false);$('pause-button').onclick=()=>setPaused(true);$('restart-button').onclick=startGame;$('again-button').onclick=startGame;
document.addEventListener('pointerlockchange',()=>{locked=document.pointerLockElement===renderer.domElement;if(state==='playing'&&!locked&&performance.now()-chapterTime>1000){/* Esc uses pause handler below */}});
const keys={};document.addEventListener('keydown',e=>{keys[e.code]=true;if(e.repeat)return;if(e.code==='Escape'&&state==='playing')setPaused(true);if(state==='playing'){if(e.code==='Digit1')setWeapon(0);if(e.code==='Digit2')setWeapon(1);if(e.code==='KeyR')reload();if(e.code==='KeyE')interact();if(e.code==='Space'&&inTruck){} }});document.addEventListener('keyup',e=>keys[e.code]=false);
document.addEventListener('mousemove',e=>{if(state==='playing'&&locked&&!inTruck){camera.rotation.order='YXZ';camera.rotation.y-=e.movementX*.0022;camera.rotation.x-=e.movementY*.0022;camera.rotation.x=Math.max(-1.35,Math.min(1.35,camera.rotation.x))}});
let mouseDown=false;renderer.domElement.addEventListener('mousedown',e=>{if(e.button===0){mouseDown=true;if(state==='playing'&&!locked)renderer.domElement.requestPointerLock?.();shoot()}});document.addEventListener('mouseup',()=>mouseDown=false);
function setWeapon(id){weapon=id;$('weapon-label').textContent=id?'MP5':'COLT PYTHON';$('weapon-mode').textContent=id?'AUTOMÁTICA':'SEMIAUTOMÁTICA';$('ammo-current').textContent=ammo[id];$('ammo-reserve').textContent=reserve[id];document.querySelectorAll('.weapon-switch span').forEach((el,i)=>el.classList.toggle('selected',i===id));tone(300+id*80,.07,'triangle',.04)}
function reload(){if(reloadTimer>0||ammo[weapon]>= (weapon?30:6)||reserve[weapon]<=0)return;reloadTimer=weapon?1.65:1.25;radio('');$('weapon-label').textContent='RECARREGANDO…';tone(230,.12,'square',.04)}
function shoot(){if(state!=='playing'||inTruck||reloadTimer>0||shootCooldown>0)return;if(ammo[weapon]<=0){tone(85,.1,'square',.05);return}ammo[weapon]--;shootCooldown=weapon?.11:.42;setWeapon(weapon);shootCooldown=weapon?.11:.42;shake=weapon?.009:.025;noise(weapon?.08:.13,weapon?.17:.25);tone(weapon?105:65,.11,'sawtooth',weapon?.12:.2);const flash=new THREE.PointLight(0xffbd70,weapon?7:13,4);flash.position.copy(camera.position).add(new THREE.Vector3(0,-.1,-.8).applyQuaternion(camera.quaternion));scene.add(flash);setTimeout(()=>scene.remove(flash),55);
 // Hit detection in a forward cone, with range and obstruction represented by the nearest target.
 const dir=new THREE.Vector3(0,0,-1).applyQuaternion(camera.quaternion),origin=camera.position.clone();let target=null,best=60;
 for(const e of enemies){if(!e.alive)continue;const p=e.group.position.clone().add(new THREE.Vector3(0,1.15,0)),to=p.sub(origin),dist=to.length(),dot=dir.dot(to.normalize());if(dist<best&&dot>(weapon?.982:.993)){best=dist;target=e}}
 if(target){target.hp-=weapon?1:3;target.group.traverse(o=>{if(o.isMesh&&o.material&&o.material.color){o.material.emissive=new THREE.Color(0x55241a);setTimeout(()=>{if(o.material.emissive)o.material.emissive.set(0)},90)}});$('hitmarker').classList.add('show');setTimeout(()=>$('hitmarker').classList.remove('show'),100);if(target.hp<=0){target.alive=false;actors.remove(target.group);killCount++;$('objective-count').textContent=`${Math.min(killCount,requiredKills)} / ${requiredKills}`;if(target.boss){radio('O guardião caiu. O abrigo está logo adiante.');tone(160,.8,'sine',.2)}else tone(100,.12,'triangle',.08);if(killCount>=requiredKills)unlockObjective()}}
}
function unlockObjective(){if(interacted)return;$('objective').textContent=chapter===1?'Encontre a chave da picape':'Vá até o sinal marcado';if(chapter===1){$('objective').textContent='Vá até a picape e pressione E';}else if(chapter===4){$('objective').textContent='Alcance o rádio marcado';}else{$('objective').textContent='Investigue o sinal marcado';}radio(chapter===1?'A chave está na ignição. A picape está no acostamento.':'O caminho está livre. Siga o marcador.')}
function interact(){if(state!=='playing')return;if(chapter===1&&killCount>=requiredKills&&!inTruck&&truck){const p=truck.position,d=Math.hypot(camera.position.x-p.x,camera.position.z-p.z);if(d<5){inTruck=true;camera.position.set(truck.position.x,2.4,truck.position.z+1);camera.rotation.set(0,Math.PI,0);$('objective').textContent='Dirija até a saída · W acelerar · A/D virar';radio('Mara: Está ouvindo? Não pare até a ponte.');tone(72,.6,'sawtooth',.1);return}}
